	dbf.w d7,abs_0_0005C9F0
	btst.b #GAME_EVENT_ESCAPE_TRIGGERED_BIT,app_game_event_flags(a6)
	bne.b abs_0_0005CA18
	bset.b #1,player_world_object_selected_item_id.l
